def release(card, readiness, size_primary, size_alt):
    ok = readiness["ok_to_submit"]
    pill = '<span class="pill good">OK TO SUBMIT</span>' if ok else '<span class="pill failed">DO NOT SUBMIT</span>'
    passed = sum(g["status"] == "passed" for g in readiness["gates"])
    headline = ("Download and submit this file." if ok else "Download for research only. <span>Do not submit.</span>")
    return f'''<section class="release" aria-labelledby="release-title">
<div class="release-heading">{pill}<span class="pill good">{passed}/{len(readiness["gates"])} automated gates passed</span><span class="pill caution">Not an organizer score</span></div>
<h2 id="release-title">{headline}</h2>
<p>A <strong>newly generated, unique</strong> model output (not a renamed or pruned historical file). The project verified it automatically: no human inspector. Primary file = all pixels finite in [0,1] (zeros outside the footprint), which avoids the portal's “Predicted values must be in range [0, 1]” error.</p>
<div class="actions"><a class="button" href="{e(readiness["primary_file"])}" download>↓ Download submission TIFF <span>{size_primary:.2f} MiB · zeros outside</span></a><a class="button secondary" href="{e(readiness["alternate_file"])}" download>Alternate: NaN outside <span>{size_alt:.2f} MiB</span></a><a class="button secondary" href="{e(card["_research"])}/readiness.json">View automated decision</a></div>
<p class="filename">{e(Path(readiness["primary_file"]).name)}</p>
<details><summary>File identity &amp; validation receipt</summary><dl><dt>SHA-256</dt><dd><code>{e(readiness["primary_sha256"])}</code></dd><dt>Alternate</dt><dd><code>{e(readiness["alternate_sha256"])}</code></dd><dt>Contract</dt><dd>One float32 band · EPSG:32611 · 3,730 × 3,292 · exact template transform · values exactly 0 or 1 · 38,000 isolated dots · none on or within 200 m of a known fault</dd><dt>Receipts</dt><dd><a href="{e(card["_research"])}/validation.json">Reopened-file validation</a> · <a href="{e(card["_research"])}/readiness.json">Gate-by-gate decision</a></dd></dl></details></section>'''


def stopped_release(card, readiness, research):
    flagged = [f for f in card["duplicate_references"] if not f["dense_reference_non_discriminating"]]
    rows = "".join(f'<li><code>{e(Path(f["reference"]).name[:72])}</code>: {f["fraction_within_3px"]:.1%} of dots within 3 px (rank ρ {f["spearman"]:.3f})</li>' for f in flagged)
    passed = sum(g["status"] == "passed" for g in readiness["gates"])
    return f'''<section class="release" aria-labelledby="release-title">
<div class="release-heading"><span class="pill failed">DO NOT SUBMIT</span><span class="pill caution">{passed}/{len(readiness["gates"])} automated gates passed</span><span class="pill caution">No TIFF published this session</span></div>
<h2 id="release-title">No file is OK to submit from this session. <span>Duplicate-stop.</span></h2>
<p>The new LSM42 model beat the repository's spatially blocked holdout best and passed every leakage check, but its final dots failed the owner's uniqueness rule (&gt;70% of dots within 3 px of an earlier raster). Per protocol the run was logged as a duplicate and stopped: no TIFF was written, so there is nothing to download or upload. The automated project inspection made this decision; no human inspector is involved.</p>
<ul class="spaced">{rows}</ul>
<div class="actions"><a class="button secondary" href="{research}/readiness.json">View automated decision</a><a class="button secondary" href="{research}/run-card.json">Run card</a><a class="button secondary" href="{research}/novelty-dots.json">Dot-stage comparisons</a></div>
<p class="filename">Logged identity: {e(card["run_id"])} · dot-array SHA-256 {e(card["candidate_values_sha256"])}</p></section>'''


def build_stopped(template, readiness, card, research):
    h = card["holdout"]
