    near = (prof["2"] + prof["3-5"] + prof["6-10"]) / total
    far = (prof["31-50"] + prof[">50"]) / total
    e3 = card["e3_crest_line_emission"]
    ind = card["independent_frame"]
    gates = "".join(f'<tr><th scope="row">{e(g["name"].replace("_", " "))}</th><td><span class="gate {e(g["status"])}">{e(g["status"])}</span></td><td>{e(g["detail"])}</td></tr>'
                    for g in readiness["gates"])
